// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type RoomTransformationProps = Record<string, any>;

const RoomTransformation: React.FC<RoomTransformationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 6,
  poorWallColor = "#B0A89F",
  poorFloorColor = "#8C8270",
  poorSofaColor = "#7A826B",
  proWallColor = "#F8F9FA",
  proFloorColor = "#DEE2E6",
  proSofaColor = "#2B2D42",
  proAccentColor = "#FFB703",
  cloudColor = "#FFFFFF",
  titleColor = "#212529",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const totalFrames = durationInSeconds * fps;
  const midFrame = Math.floor(totalFrames / 2);
  const cloudStart = midFrame - Math.floor(fps * 0.8);
  const cloudEnd = midFrame + Math.floor(fps * 0.8);

  const isRoomB = frame > midFrame;
  const floorY = height * 0.6;

  // --- CLOUD TRANSITION LOGIC ---
  const cloudOpacity = interpolate(
    frame,
    [cloudStart, cloudStart + 15, cloudEnd - 15, cloudEnd],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cloudScale = interpolate(
    frame,
    [cloudStart, midFrame, cloudEnd],
    [0, 6, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // --- ROOM A (POOR STAGING) ANIMATIONS ---
  const artTiltSpring = spring({ frame: frame - 15, fps, config: { damping: 15 } });
  const artRotation = interpolate(artTiltSpring, [0, 1], [5, 22]);
  const isFlickerOn = frame % 12 < 8 || frame % 20 === 0;
  const lightOpacity = isFlickerOn ? 1 : 0.2;

  // --- ROOM B (PRO STAGING) ANIMATIONS ---
  const proIntroSpring = spring({ frame: frame - midFrame, fps, config: { damping: 14 } });
  const slideUp = interpolate(proIntroSpring, [0, 1], [60, 0]);
  const fadeUp = interpolate(proIntroSpring, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGroteskFamily }}>
      
      {/* --- TITLE BADGE --- */}
      <div
        style={{
          position: "absolute",
          top: height * 0.12,
          left: "50%",
          transform: "translateX(-50%)",
          fontSize: 48,
          fontWeight: "bold",
          letterSpacing: 4,
          color: isRoomB ? titleColor : "#FFF",
          backgroundColor: isRoomB ? "rgba(255,255,255,0.8)" : "rgba(0,0,0,0.2)",
          padding: "20px 60px",
          borderRadius: 40,
          zIndex: 10,
          transition: "none",
        }}
      >
        {isRoomB ? "AFTER" : "BEFORE"}
      </div>

      {/* --- ROOM RENDERER --- */}
      {!isRoomB ? (
        // --- ROOM A: POORLY STAGED ---
        <div style={{ position: "absolute", width: "100%", height: "100%", transition: "none" }}>
          <div style={{ position: "absolute", top: 0, width: "100%", height: floorY, backgroundColor: poorWallColor, transition: "none" }} />
          <div style={{ position: "absolute", top: floorY, width: "100%", height: height - floorY, backgroundColor: poorFloorColor, transition: "none" }} />
          
          {/* Bare Bulb */}
          <div style={{ position: "absolute", top: 0, left: "40%", width: 4, height: 300, backgroundColor: "#333", transition: "none" }} />
          <div style={{
            position: "absolute", top: 300, left: "40%", width: 40, height: 40, backgroundColor: "#FFD700",
            borderRadius: "50%", transform: "translateX(-18px)", opacity: lightOpacity, transition: "none"
          }} />

          {/* Crooked Art */}
          <div style={{
            position: "absolute", top: floorY - 450, left: "65%", width: 140, height: 180,
            backgroundColor: "#CD853F", border: "12px solid #4A3B32",
            transform: `rotate(${artRotation}deg)`, transition: "none"
          }}>
             <div style={{ position: "absolute", top: "10%", left: "10%", width: "80%", height: "80%", backgroundColor: "#E6D5B8", transition: "none" }} />
          </div>

          {/* Skewed Small Rug */}
          <div style={{
            position: "absolute", top: floorY + 120, left: "25%", width: width * 0.45, height: 160,
            backgroundColor: "#6B5B45", transform: "rotate(-12deg) skewX(-15deg)", transition: "none"
          }} />

          {/* Clutter Boxes */}
          <div style={{ position: "absolute", top: floorY + 300, left: "65%", width: 80, height: 60, backgroundColor: "#A0522D", transform: "rotate(18deg)", transition: "none" }} />
          <div style={{ position: "absolute", top: floorY + 320, left: "75%", width: 50, height: 50, backgroundColor: "#4682B4", transform: "rotate(-25deg)", transition: "none" }} />

          {/* Messy Sofa */}
          <div style={{
            position: "absolute", top: floorY - 80, left: "30%", width: width * 0.6, height: 200,
            backgroundColor: poorSofaColor, borderRadius: "20px 5px 30px 10px",
            transform: "rotate(4deg)", transition: "none"
          }} />
        </div>
      ) : (
        // --- ROOM B: PROFESSIONALLY STAGED ---
        <div style={{ position: "absolute", width: "100%", height: "100%", transition: "none" }}>
          <div style={{ position: "absolute", top: 0, width: "100%", height: floorY, backgroundColor: proWallColor, transition: "none" }} />
          <div style={{ position: "absolute", top: floorY, width: "100%", height: height - floorY, backgroundColor: proFloorColor, transition: "none" }} />

          {/* Centered Large Rug */}
          <div style={{
            position: "absolute", top: floorY + 80, left: "50%", width: width * 0.85, height: 280,
            backgroundColor: "#F1F3F5", transform: `translate(-50%, ${slideUp}px)`,
            borderRadius: 24, opacity: fadeUp, transition: "none"
          }} />

          {/* Potted Plant */}
          <div style={{
            position: "absolute", top: floorY - 280, left: "15%", width: 160, height: 260,
            backgroundColor: "#40916C", transform: `translate(-50%, ${slideUp * 1.2}px)`,
            borderRadius: "80px 80px 20px 20px", opacity: fadeUp, transition: "none"
          }} />
          <div style={{
            position: "absolute", top: floorY - 60, left: "15%", width: 90, height: 140,
            backgroundColor: "#B08968", transform: `translate(-50%, ${slideUp * 1.2}px)`,
            borderRadius: "10px 10px 40px 40px", opacity: fadeUp, transition: "none"
          }} />

          {/* Perfectly Aligned Triptych Art */}
          {[0, 1, 2].map((i) => {
            const artSpring = spring({ frame: frame - midFrame - (i * 4), fps, config: { damping: 14 } });
            const artSlide = interpolate(artSpring, [0, 1], [40, 0]);
            const artFade = interpolate(artSpring, [0, 1], [0, 1]);
            return (
              <div key={`art-${i}`} style={{
                position: "absolute", top: floorY - 480, left: `${25 + i * 25}%`, width: width * 0.18, height: width * 0.24,
                backgroundColor: "#FFF", border: "6px solid #212529",
                transform: `translate(-50%, ${artSlide}px)`, opacity: artFade, transition: "none"
              }}>
                <div style={{
                  position: "absolute", top: "20%", left: "20%", width: "60%", height: "60%",
                  backgroundColor: proAccentColor, borderRadius: i === 1 ? "50%" : "8px", transition: "none"
                }} />
              </div>
            );
          })}

          {/* Sleek Modern Chandelier */}
          <div style={{ position: "absolute", top: 0, left: "50%", width: 4, height: 240, backgroundColor: "#212529", transform: `translate(-50%, ${slideUp}px)`, opacity: fadeUp, transition: "none" }} />
          <div style={{ position: "absolute", top: 240, left: "50%", width: 220, height: 8, backgroundColor: "#212529", transform: `translate(-50%, ${slideUp}px)`, opacity: fadeUp, transition: "none" }} />
          <div style={{ position: "absolute", top: 244, left: "38%", width: 50, height: 50, backgroundColor: proAccentColor, transform: `translate(-50%, ${slideUp}px)`, borderRadius: "50%", opacity: fadeUp, transition: "none" }} />
          <div style={{ position: "absolute", top: 244, left: "62%", width: 50, height: 50, backgroundColor: proAccentColor, transform: `translate(-50%, ${slideUp}px)`, borderRadius: "50%", opacity: fadeUp, transition: "none" }} />

          {/* Centered Modern Sofa */}
          <div style={{
            position: "absolute", top: floorY - 140, left: "50%", width: width * 0.75, height: 220,
            backgroundColor: proSofaColor, transform: `translate(-50%, ${slideUp}px)`,
            borderRadius: 40, opacity: fadeUp, transition: "none"
          }}>
            {/* Sofa Cushions */}
            <div style={{ position: "absolute", top: 0, left: "0%", width: "50%", height: "50%", backgroundColor: "rgba(255,255,255,0.05)", borderRadius: "40px 0 0 0", transition: "none" }} />
            <div style={{ position: "absolute", top: 0, right: "0%", width: "50%", height: "50%", backgroundColor: "rgba(0,0,0,0.1)", borderRadius: "0 40px 0 0", transition: "none" }} />
          </div>

          {/* Coffee Table */}
          <div style={{
            position: "absolute", top: floorY + 120, left: "50%", width: width * 0.4, height: 60,
            backgroundColor: "#DEB887", transform: `translate(-50%, ${slideUp * 0.8}px)`,
            borderRadius: 30, opacity: fadeUp, transition: "none"
          }} />
        </div>
      )}

      {/* --- CLOUD TRANSITION LAYER --- */}
      {cloudOpacity > 0 && (
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 600,
          height: 600,
          transform: `translate(-50%, -50%) scale(${cloudScale})`,
          opacity: cloudOpacity,
          pointerEvents: "none",
          zIndex: 100,
          transition: "none"
        }}>
          <svg viewBox="0 0 200 200" width="100%" height="100%" style={{ transition: "none" }}>
            <circle cx="100" cy="100" r="60" fill={cloudColor} style={{ transition: "none" }} />
            <circle cx="50" cy="120" r="50" fill={cloudColor} style={{ transition: "none" }} />
            <circle cx="150" cy="120" r="50" fill={cloudColor} style={{ transition: "none" }} />
            <circle cx="60" cy="70" r="55" fill={cloudColor} style={{ transition: "none" }} />
            <circle cx="140" cy="70" r="55" fill={cloudColor} style={{ transition: "none" }} />
            <circle cx="100" cy="50" r="50" fill={cloudColor} style={{ transition: "none" }} />
          </svg>
        </div>
      )}

    </AbsoluteFill>
  );
};

export default RoomTransformation;